+CHANGED_FILES=$(git diff --name-only --diff-filter=d --merge-base autoformatter-remote/${BASE_REF} megatron/core 'megatron/rl/shared_prefix_*.py' megatron/rl/tree_layout.py tests/ | grep '\.py$' || true)
